*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f5f5fb;font-synthesis:none;text-rendering:optimizeLegibility;--muted:#a9a9bb;--line:rgba(255,255,255,.12);--panel:rgba(19,22,34,.91)} body{margin:0;background:#10131e;overflow:hidden}.game-shell{position:relative;width:100vw;height:100dvh;min-height:600px;overflow:hidden;background:radial-gradient(ellipse at 50% 32%,#755fa4 0,#2b2c51 43%,#111522 78%)}#battle-scene{position:absolute;inset:0;z-index:0}#battle-scene canvas{width:100%;height:100%;display:block}.scene-vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(8,10,19,.52) 0%,transparent 20%,transparent 47%,rgba(11,13,22,.03) 56%,rgba(10,12,20,.48) 100%),linear-gradient(90deg,rgba(10,12,21,.2),transparent 30%,transparent 70%,rgba(10,12,21,.2))}.topbar{position:absolute;z-index:5;top:0;left:0;right:0;height:76px;padding:0 5.2%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(16,18,29,.55),rgba(16,18,29,.12));}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none;font-size:12px;font-weight:800;letter-spacing:1.55px}.brand i{font-style:normal;color:#9190a7;margin:0 3px}.brand b{font-weight:600;color:#c1bfd0}.brand-mark{height:31px;width:31px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.55);border-radius:50%;font-family:'Space Grotesk';font-size:17px;font-weight:700;box-shadow:0 0 14px #c5a6ff55}.top-meta{display:flex;align-items:center;gap:9px;color:#d4d1e0;font-size:9px;font-weight:700;letter-spacing:1.5px}.live-dot,.copy-dot{height:6px;width:6px;border-radius:50%;background:#76e3bc;box-shadow:0 0 8px #76e3bc}.meta-divider{height:15px;width:1px;background:var(--line);margin:0 7px}.sound-button{margin-left:17px;padding:8px 11px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.13);border-radius:5px;color:#f4f3fa;font:700 10px 'DM Sans';letter-spacing:.9px;cursor:pointer}.sound-button span{font-size:8px;margin-left:4px;color:#c3c2d0}.arena-label{position:absolute;z-index:2;top:98px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;color:rgba(255,255,255,.67);font-size:9px;letter-spacing:3px;font-weight:700;white-space:nowrap}.arena-line{width:28px;height:1px;background:rgba(255,255,255,.34)}.status-card{position:absolute;z-index:4;width:260px;padding:15px 17px 13px;border:1px solid rgba(255,255,255,.23);border-radius:10px;background:linear-gradient(135deg,rgba(29,31,45,.84),rgba(26,27,42,.61));backdrop-filter:blur(12px);box-shadow:0 12px 35px #0e102144}.enemy-status{top:18%;right:9.2%}.player-status{bottom:34%;left:8.2%}.status-top{display:flex;justify-content:space-between;align-items:flex-start}.pokemon-title{font:700 22px 'Space Grotesk';letter-spacing:-.7px}.gender{font:600 14px 'DM Sans';color:#ffb1d3;padding-left:4px}.level-line{display:flex;align-items:center;gap:5px;margin-top:6px;color:#d2cfdd;font-size:9px;letter-spacing:.8px;font-weight:700}.type-pill{font-size:7px;letter-spacing:.65px;padding:3px 6px;border-radius:3px;margin-left:3px;background:#a64dce;color:white}.type-electric{background:#dca52c;color:#fff7d5}.type-poison{background:#9652bd}.type-ghost{background:#6550a9}.ball-icon{width:19px;height:19px;border:1px solid #ffffff50;border-radius:50%;font-size:10px;display:grid;place-items:center;color:#fff9;margin:1px 3px 0 0}.hp-track{margin-top:13px;width:100%;height:7px;background:#11131a;border-radius:5px;overflow:hidden}.hp-fill{height:100%;width:100%;border-radius:5px;background:linear-gradient(90deg,#4cdaa1,#9ced9e);transition:width .65s cubic-bezier(.2,.8,.2,1),background .35s;box-shadow:0 0 8px #61e9ac66}.hp-fill.warning{background:linear-gradient(90deg,#e7bd53,#ffe17b)}.hp-fill.danger{background:linear-gradient(90deg,#ed6075,#ff8a93)}.hp-numbers{margin-top:5px;display:flex;justify-content:space-between;color:#c4c1ce;font-size:9px;font-weight:700;letter-spacing:.7px}.xp-track{height:2px;background:#252839;border-radius:2px;margin-top:8px;overflow:hidden}.xp-fill{height:100%;width:68%;background:#87a9ff;box-shadow:0 0 6px #87a9ff}.battle-toast{position:absolute;z-index:4;left:50%;top:58%;transform:translate(-50%,8px);padding:9px 16px;display:flex;align-items:center;gap:9px;border-radius:30px;background:rgba(15,17,27,.7);border:1px solid rgba(255,255,255,.12);font-size:11px;color:#f1eefb;opacity:0;transition:.3s;backdrop-filter:blur(8px);white-space:nowrap;pointer-events:none}.battle-toast.visible{opacity:1;transform:translate(-50%,0)}.toast-spark{color:#ffe28d}.battle-panel{position:absolute;z-index:5;bottom:0;left:0;right:0;min-height:257px;padding:25px max(5.2%,calc((100% - 1200px)/2)) 15px;display:grid;grid-template-columns:minmax(230px, .75fr) minmax(430px,1.35fr);gap:38px;align-items:center;border-top:1px solid rgba(255,255,255,.15);background:linear-gradient(120deg,rgba(19,21,34,.97),rgba(27,29,44,.95));box-shadow:0 -16px 50px #090a1455;backdrop-filter:blur(18px)}.battle-copy{align-self:start;padding-top:13px}.copy-kicker{display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:2px;font-weight:800;color:#aaa9bd}.copy-dot{height:5px;width:5px;background:#f8cf78;box-shadow:0 0 7px #f8cf78}.battle-message{margin-top:12px;max-width:290px;font:600 25px/1.26 'Space Grotesk';letter-spacing:-.8px;color:#f6f4fa}.battle-message b{color:#ffda78;font-weight:700}.action-area{width:100%}.move-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.move-card{position:relative;min-width:0;height:61px;padding:0 11px;display:flex;align-items:center;gap:10px;text-align:left;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.11);border-radius:6px;color:white;cursor:pointer;transition:background .16s,border .16s,transform .16s}.move-card:hover:not(:disabled){background:rgba(255,255,255,.105);border-color:#ffffff55;transform:translateY(-2px)}.move-card:active:not(:disabled){transform:translateY(0)}.move-card:disabled{opacity:.42;cursor:not-allowed}.move-icon{flex:0 0 31px;width:31px;height:31px;border-radius:5px;background:rgba(245,193,74,.15);color:#ffd86f;display:grid;place-items:center;font-size:22px;font-weight:700}.normal-move .move-icon{background:rgba(172,174,197,.12);color:#c6c6d6;font-size:16px}.steel-move .move-icon{background:rgba(134,165,226,.14);color:#a7c4ff}.switch-icon{background:rgba(130,229,195,.13);color:#83e5c4}.move-info{display:flex;min-width:0;flex-direction:column;gap:5px}.move-info strong{font:700 12px 'Space Grotesk';white-space:nowrap}.move-info small{color:#a5a4b7;font-size:7px;font-weight:700;letter-spacing:.75px;white-space:nowrap}.move-info small i{font-style:normal;color:#6b6c80;padding:0 2px}.move-pp{margin-left:auto;align-self:flex-start;padding-top:10px;font-size:9px;font-weight:700;color:#ece9f4;white-space:nowrap}.move-pp i{font-style:normal;color:#858597;font-weight:500}.move-arrow{display:none;color:#fff9;font-size:14px}.action-footer{display:flex;justify-content:space-between;margin-top:10px;color:#88899f;font-size:8px;font-weight:700;letter-spacing:1px}.action-footer kbd{font:700 8px 'DM Sans';color:#d7d4e4;border:1px solid #656579;border-radius:3px;padding:1px 4px;margin-right:2px}.turn-note i{color:#f4ce79;font-style:normal;margin:0 3px}.battle-log{position:absolute;z-index:4;bottom:269px;left:5.2%;height:28px;display:flex;align-items:center;gap:8px;color:#e3e1ec;font-size:10px;text-shadow:0 1px 4px #000;transition:opacity .2s}.log-mark{color:#f9d177}.battle-log button{background:transparent;border:0;color:#e3e1ec;cursor:pointer;font-size:14px;margin-left:4px}.log-history{position:absolute;z-index:8;bottom:301px;left:5%;width:min(360px,90%);max-height:160px;overflow:auto;background:#181a28ed;border:1px solid var(--line);border-radius:8px;padding:12px;color:#c6c4d2;font-size:11px;line-height:1.7;backdrop-filter:blur(12px)}.log-history div+div{border-top:1px solid #ffffff12}.hidden{display:none!important}.sub-panel{display:grid;grid-template-columns:1fr 1fr;gap:8px}.party-card{height:61px;display:flex;align-items:center;gap:10px;padding:7px 12px;background:#ffffff0b;border:1px solid #ffffff1c;border-radius:6px;text-align:left;color:white;cursor:pointer}.party-card:hover{background:#ffffff17}.party-orb{height:30px;width:30px;border-radius:50%;display:grid;place-items:center;font-size:17px;background:#ffe278;color:#874f3a}.party-name{font:700 12px 'Space Grotesk'}.party-hp{font-size:9px;color:#aaa9bd;margin-top:3px}.party-back{grid-column:span 2;color:#b9b8c8;background:transparent;border:0;text-align:left;font:600 10px 'DM Sans';cursor:pointer;padding:3px}.mobile-hint{display:none}.shake{animation:shake .38s ease}.flash{animation:flash .4s ease}@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px)}60%{transform:translateX(6px)}80%{transform:translateX(-3px)}}@keyframes flash{0%,100%{filter:none}35%{filter:brightness(2.2)}}
@media(max-width:760px){.game-shell{min-height:560px}.topbar{height:59px;padding:0 18px}.brand{font-size:9px;letter-spacing:.9px;gap:7px}.brand-mark{width:26px;height:26px}.brand b{display:none}.top-meta{font-size:8px;letter-spacing:.9px;gap:6px}.sound-button{margin-left:5px;padding:7px}.sound-button span{display:none}.arena-label{top:74px;font-size:8px}.arena-line{width:17px}.enemy-status{top:16%;right:4%;width:195px;padding:11px 12px}.player-status{bottom:43%;left:4%;width:195px;padding:11px 12px}.pokemon-title{font-size:18px}.status-card .hp-track{margin-top:9px;height:6px}.status-card .hp-numbers{font-size:8px}.type-pill{font-size:6px;padding:3px 4px}.battle-toast{top:49%;font-size:9px}.battle-panel{min-height:290px;padding:15px 16px 12px;display:flex;flex-direction:column;align-items:stretch;gap:10px}.battle-copy{padding:0;min-height:45px}.copy-kicker{font-size:8px}.battle-message{font-size:19px;margin-top:5px;max-width:none}.move-grid{gap:7px}.move-card{height:57px;padding:0 8px;gap:7px}.move-icon{flex-basis:26px;width:26px;height:26px;font-size:18px}.move-info strong{font-size:10px}.move-info small{font-size:6px;letter-spacing:.5px}.move-pp{font-size:8px;padding-top:8px}.action-footer{margin-top:7px;font-size:7px}.battle-log{bottom:300px;left:16px;font-size:9px}.log-history{bottom:325px;left:4%;}.mobile-hint{position:absolute;display:block;z-index:4;right:15px;bottom:304px;color:#c6c4d3;font-size:7px;letter-spacing:1px;opacity:.7}.player-status .xp-track{margin-top:6px}}
@media(max-width:380px){.move-card{gap:5px;padding:0 6px}.move-info strong{font-size:9px}.move-info small{letter-spacing:.2px}.move-pp{font-size:7px}.battle-panel{padding-left:12px;padding-right:12px}.status-card{width:180px}.player-status{bottom:44%}.enemy-status{top:15%}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const mount=document.querySelector('#battle-scene');
const scene=new THREE.Scene();
scene.background=new THREE.Color('#3c3b66');
scene.fog=new THREE.FogExp2('#393957',.027);
const camera=new THREE.PerspectiveCamera(36,innerWidth/innerHeight,.1,100);
camera.position.set(0,7.3,17.4);camera.lookAt(0,1.6,0);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;renderer.outputColorSpace=THREE.SRGBColorSpace;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#d9d4ff','#333246',2.1));
const keyLight=new THREE.DirectionalLight('#fff0d6',3.3);keyLight.position.set(-5,10,7);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);scene.add(keyLight);
const rimLight=new THREE.PointLight('#8fbaff',65,24);rimLight.position.set(4,5,-4);scene.add(rimLight);
const warmLight=new THREE.PointLight('#ffc889',48,22);warmLight.position.set(-5,4,3);scene.add(warmLight);
const mat=(color,roughness=.72,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={ground:mat('#272b43'),stage:mat('#404463'),rim:mat('#7d82ad',.34,.4),yellow:mat('#f9c846'),yellowLight:mat('#ffdc72'),orange:mat('#f47742'),red:mat('#df4a50'),brown:mat('#754631'),dark:mat('#302d40'),white:mat('#fff2d6'),black:mat('#262335'),purple:mat('#8661bd'),purpleLight:mat('#a184d2'),pink:mat('#e987a8'),teal:mat('#65d5c3'),blue:mat('#4789d1'),eye:mat('#fff1bd',.25),iris:mat('#643c76',.25),shine:mat('#ffffff',.2)};
function mesh(geo,material,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function ball(parent,material,x,y,z,sx,sy=sx,sz=sx){const m=mesh(new THREE.SphereGeometry(1,24,16),material,parent,x,y,z);m.scale.set(sx,sy,sz);return m}
function cone(parent,material,x,y,z,r,h,rotX=0,rotZ=0){const m=mesh(new THREE.ConeGeometry(r,h,12),material,parent,x,y,z);m.rotation.set(rotX,0,rotZ);return m}
function limb(parent,material,a,b,r1,r2=r1){const va=new THREE.Vector3(...a),vb=new THREE.Vector3(...b),d=vb.clone().sub(va);const m=mesh(new THREE.CylinderGeometry(r2,r1,d.length(),12),material,parent);m.position.copy(va.add(vb).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return m}
function makePikachu(){const g=new THREE.Group();ball(g,mats.yellow,0,.92,0,.62,.75,.49);ball(g,mats.yellowLight,0,1.43,.04,.57,.53,.48);ball(g,mats.yellow,0,1.67,.02,.57,.54,.48);
for(const side of [-1,1]){const ear=mesh(new THREE.ConeGeometry(.14,.8,12),mats.yellow,g,side*.37,2.2,-.01);ear.rotation.z=side*-.24;const tip=mesh(new THREE.ConeGeometry(.105,.32,12),mats.dark,g,side*.44,2.55,-.01);tip.rotation.z=side*-.24;ball(g,mats.black,side*.22,1.8,.43,.055,.073,.035);ball(g,mats.shine,side*.23,1.82,.46,.017,.02,.012);ball(g,mats.red,side*.47,1.5,.37,.14,.12,.045);limb(g,mats.yellow,[side*.43,.9,.03],[side*.65,.58,.17],.12);ball(g,mats.yellow,side*.17,.22,.16,.2,.17,.3)}
ball(g,mats.brown,0,1.28,.463,.1,.07,.025);ball(g,mats.brown,-.13,1.17,.44,.07,.035,.02);ball(g,mats.brown,.13,1.17,.44,.07,.035,.02);
const tail=new THREE.Group();tail.position.set(.49,1.12,-.2);tail.rotation.z=-.42;g.add(tail);limb(tail,mats.brown,[0,0,0],[.15,.22,0],.1);limb(tail,mats.yellow, [.15,.22,0],[.43,.54,0],.12);const t1=mesh(new THREE.BoxGeometry(.4,.42,.13),mats.yellow,tail,.54,.75,0);t1.rotation.z=-.45;const t2=mesh(new THREE.BoxGeometry(.32,.32,.14),mats.yellow,tail,.56,1.04,0);t2.rotation.z=.48;const t3=mesh(new THREE.BoxGeometry(.34,.32,.14),mats.yellow,tail,.78,1.02,0);t3.rotation.z=-.48;ball(tail,mats.yellow,.79,.78,0,.18,.18,.09);g.userData.tail=tail;g.userData.kind='pikachu';return g}
function makeGengar(){const g=new THREE.Group();ball(g,mats.purple,0,1.13,0,.88,.92,.72);ball(g,mats.purpleLight,0,1.45,.38,.72,.55,.44);
for(let i=0;i<9;i++){const a=(i/8)*Math.PI-Math.PI/2;const x=Math.sin(a)*.72;const y=1.2+Math.cos(a)*.48;cone(g,mats.purple,x,y,.01,.27,.54,0,-x*.35)}
for(const s of [-1,1]){ball(g,mats.eye,s*.28,1.52,.75,.2,.28,.09);ball(g,mats.iris,s*.28,1.5,.826,.105,.17,.035);ball(g,mats.shine,s*.3,1.57,.855,.038,.05,.016);cone(g,mats.purple,s*.42,2.02,-.05,.17,.43,0,s*-.34);ball(g,mats.dark,s*.59,.54,.12,.25,.2,.34)}
const mouth=ball(g,mats.dark,0,.99,.777,.39,.2,.05);mouth.rotation.z=.08;for(let i=0;i<5;i++){cone(g,mats.white,-.27+i*.135,.88,.81,.065,.15,Math.PI,0)}g.userData.kind='gengar';return g}
function makeEevee(){const g=new THREE.Group();ball(g,mats.brown,0,.8,0,.57,.62,.47);ball(g,mats.brown,0,1.42,.02,.52,.49,.43);ball(g,mat('#e6c19a'),0,1.04,.42,.53,.36,.19);ball(g,mat('#f3d9b6'),0,1.48,.39,.47,.3,.16);
for(const s of [-1,1]){const ear=mesh(new THREE.ConeGeometry(.17,.72,12),mats.brown,g,s*.34,2.03,-.05);ear.rotation.z=-s*.18;ball(g,mat('#d58c83'),s*.34,2.04,.05,.09,.22,.06);ball(g,mats.black,s*.19,1.56,.54,.04,.06,.025);ball(g,mats.brown,s*.2,.2,.14,.16,.17,.26)}
ball(g,mats.black,0,1.27,.56,.07,.05,.04);for(let i=0;i<4;i++)cone(g,mats.white,-.25+i*.16,.91,.56,.045,.12,Math.PI);g.userData.kind='eevee';return g}
function makeCharizard(){const g=new THREE.Group();ball(g,mats.orange,0,.93,0,.58,.71,.45);ball(g,mats.orange,0,1.55,.02,.48,.48,.39);ball(g,mats.white,0,1.38,.36,.31,.16,.08);
for(const s of [-1,1]){ball(g,mats.eye,s*.19,1.67,.36,.09,.13,.04);ball(g,mats.iris,s*.19,1.66,.398,.04,.09,.02);cone(g,mats.orange,s*.25,1.98,.02,.12,.32,0,s*-.25);limb(g,mats.orange,[s*.39,1.14,0],[s*.62,.89,.16],.14);ball(g,mats.orange,s*.18,.2,.1,.18,.18,.26)}
for(const s of [-1,1]){const wing=mesh(g,new THREE.BufferGeometry(),mats.orange,g,s*.57,1.42,-.22);const shape=new THREE.Shape();shape.moveTo(0,0);shape.lineTo(s*.56,.72);shape.lineTo(s*.5,.1);shape.lineTo(s*.34,.32);shape.lineTo(s*.2,-.07);shape.lineTo(0,0);wing.geometry=new THREE.ShapeGeometry(shape);wing.material.side=THREE.DoubleSide;wing.rotation.y=s*.35;}
limb(g,mats.orange,[.27,.65,-.23],[.75,.48,-.4],.08);cone(g,mats.red,.83,.63,-.4,.15,.37,0,0);cone(g,mat('#ffd452'),.83,.77,-.4,.09,.26,0,0);g.userData.kind='charizard';return g}
function makeCreature(kind){return ({pikachu:makePikachu,gengar:makeGengar,eevee:makeEevee,charizard:makeCharizard}[kind])()}

// Stage, battle pads, and the distant plateau skyline.
const floor=mesh(new THREE.PlaneGeometry(200,200),mats.ground,scene,0,-.24,0);floor.rotation.x=-Math.PI/2;
for(const [x,z,r] of [[-2.45,1.15,2],[2.5,-1.45,1.82]]){const pad=mesh(new THREE.CylinderGeometry(r,r,.18,64),mats.stage,scene,x,-.1,z);pad.receiveShadow=true;const rim=mesh(new THREE.CylinderGeometry(r+.055,r+.055,.12,64,1,true),mats.rim,scene,x,-.12,z);rim.material.side=THREE.DoubleSide;const ring=mesh(new THREE.TorusGeometry(r*.88,.013,8,90),new THREE.MeshBasicMaterial({color:'#adb6f4',transparent:true,opacity:.35}),scene,x,-.002,z);ring.rotation.x=Math.PI/2;}
const horizon=new THREE.Group();scene.add(horizon);
for(let i=0;i<21;i++){const x=-18+i*1.8;const h=2+Math.abs(Math.sin(i*1.91))*5;const tower=mesh(new THREE.BoxGeometry(.55,h,.38),mat(i%3?'#56516f':'#696080'),horizon,x,h/2-1,-12);tower.material.transparent=true;tower.material.opacity=.65;const glow=mesh(new THREE.BoxGeometry(.035,h*.75,.04),new THREE.MeshBasicMaterial({color:i%2?'#b698ff':'#8ad6dd',transparent:true,opacity:.5}),horizon,x+.12,h/2-1,-11.78)}
for(let i=0;i<8;i++){const hill=mesh(new THREE.ConeGeometry(4+Math.random()*2,4+Math.random()*3,4),mat(i%2?'#41415f':'#484462'),horizon,-17+i*4.8,1.4,-18);hill.rotation.y=Math.PI/4;hill.material.transparent=true;hill.material.opacity=.67}
for(let i=0;i<30;i++){const star=mesh(new THREE.SphereGeometry(.025+Math.random()*.025,8,6),new THREE.MeshBasicMaterial({color:i%3?'#d8cbff':'#a0e8e2'}),scene,(Math.random()-.5)*27,3+Math.random()*9,-9-Math.random()*8);star.userData.baseY=star.position.y}
const fighters={player:{},enemy:{}};
function placeFighter(side,kind){const f=fighters[side];if(f.group)scene.remove(f.group);const g=makeCreature(kind);g.position.set(side==='player'?-2.45:2.5,0,side==='player'?1.1:-1.45);if(side==='enemy')g.scale.setScalar(.85);scene.add(g);f.group=g;f.base=g.position.clone();return g}
placeFighter('player','pikachu');placeFighter('enemy','gengar');

